"""Complete Mexican and Italian mayonnaise dishes and retain an equivalent source."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
out=root.parent.parent/'outputs/SavorShelf-Content-Repairs'
db=sqlite3.connect(out/'grouped-work.sqlite3')
rows=json.loads((out/'dressing-candidates.json').read_text(encoding='utf-8'))

records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
newids=[]
def src(n):return json.loads(db.execute('select record from recipes where id=?',(rows[n]['id'],)).fetchone()[0])
def I(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def oil(a):return I('oil',a,'ml','olive oil','Use the same volume of a mild sunflower or rapeseed oil.')
def vinegar(a,kind='white wine'):return I('vinegar',a,'ml',kind+' vinegar','Use the same volume of cider vinegar for a different flavor.')
def salt(a=.5):return I('salt',a,'tsp','fine salt','Reduce or omit to taste.')
def pepper(a=.25):return I('pepper',a,'tsp','ground black pepper','Use the same amount of ground white pepper, or omit.')
def parsley(a=1):return I('parsley',a,'tsp','fresh parsley, finely chopped','Use the same amount of finely chopped chives.')
def tk(k):return '{{'+k+'}}'
STORE='Use promptly, or cover and refrigerate at 4°C (40°F) or colder for up to 3 days. Whisk again before serving; oil and vinegar naturally separate. This is a fresh dressing, not a shelf-stable preserve.'
NOTE=' Spoon measures use the app’s modern 15 ml tablespoon and 5 ml teaspoon. Yields, missing quantities and preparation times are modern estimates, not recovered historical measurements. Not kitchen-tested. Scaling changes ingredient amounts, not preparation times.'
def add(n,title,y,t,desc,items,steps,notes):
 s=src(n);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Condiments',servings=y,yieldUnit='servings',minutes=t,totalMinutes=t,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T20:00:00Z',notes=notes+NOTE,source=s['recipe']['source']+' SavorShelf measured adaptation.');r.pop('variants',None);r['sourceAliases']=[]
 records[r['id']]=dict(sourceId=r['id'],bodySha256=s['bodySha256'],recipe=r);newids.append(r['id']);return r
def variant(r,id,label,items,steps):r.setdefault('variants',[]).append(dict(id=id,label=label,ingredients=items,steps=steps))
def yolks(a):return I('yolks',a,'','large pasteurized egg yolks','Use 18 g commercially pasteurized liquid egg yolk per yolk; do not substitute unpasteurized raw egg.')
def mustard(a):return I('mustard',a,'tsp','dry mustard powder','Use the same volume of prepared Dijon mustard for a milder flavor.')
def cayenne():return I('cayenne',.0625,'tsp','ground cayenne pepper','Omit for a mild mayonnaise.')
def lemon(a):return I('lemon',a,'ml','lemon juice','Use the same volume of lime juice for a different flavor.')
COLD='Transfer to a clean covered container and refrigerate immediately at 4°C (40°F) or colder. Use within 3 days, using a clean spoon each time. This is fresh homemade mayonnaise, not a shelf-stable preserve.'
def emulsion(keys):
 return ['Set a clean small bowl on a damp towel to steady it. Whisk '+', '.join(tk(k) for k in keys)+' until smooth.','Measure {{oil}} into a jug. Whisk continuously while adding it drop by drop at first. Once the mixture is thick and glossy, add the remaining measured oil in a very thin stream, whisking until fully incorporated. Stop pouring if oil pools on the surface and whisk until it blends in.','The finished mayonnaise should be smooth and creamy. If it separates, put 1 teaspoon cold drinking water in a clean bowl and whisk the separated mixture into it a few drops at a time; this small repair addition changes the yield slightly.',COLD]
def eggsource(r):r['source']+=' Raw-yolk handling uses commercially pasteurized egg: https://www.foodsafety.gov/people-at-risk .';return r
def eggs(a):return I('eggs',a,'','large eggs for hard boiling','Use large pasteurized shell eggs if preferred; cook until the yolks are firm.')
def water(a,k='water'):return I(k,a,'ml','drinking water','Use the same volume of drinking water, topping up to cover as directed.')
def boil():return ['Put {{eggs}} in a saucepan with {{water}}, adding more water only if needed to cover by about 2 cm. Bring to a boil, cover, remove from heat and stand for 12 minutes. Cool under cold running water, peel and cut open; the yolks must be firm throughout.']
END='Keep covered at 4°C (40°F) or colder until serving. Refrigerate leftovers within 2 hours and use within 2 days. Do not leave the platter at room temperature for more than 2 hours.'
REF=' Cooking endpoints: https://www.foodsafety.gov/food-safety-charts/safe-minimum-internal-temperatures . Variety meats: https://ask.fsis.usda.gov/article/What-are-the-recommended-cooking-times-for-veal .'
def finish(r):r['category']='Main dishes';r['source']+=REF;return eggsource(r)

def fish(a):return I('fish',a,'g','raw boneless skinless white fish fillets','Use the same weight of hake, cod or sea bass fillets; check carefully for bones.')
def lettuce(a):return I('lettuce',a,'g','lettuce leaves, washed and thoroughly dried','Use the same weight of romaine or butterhead lettuce.')
def poultry(r):
 vi=[I('chicken',i['amount'],i['unit'],'raw boneless skinless chicken breast','Use the fish base recipe if preferred.') if i['key']=='fish' else copy.deepcopy(i) for i in r['ingredients']]
 vs=copy.deepcopy(r['steps']);vs[0]='Bring {{fishwater}} to a gentle simmer in a wide pan. Add {{chicken}} and poach gently for about 15–20 minutes, until the thickest part reaches 74°C (165°F). Lift out, drain and cut into bite-size pieces. Spread in a shallow container and refrigerate promptly, within 2 hours of cooking, until cold, about 45–60 minutes.'
 vs=[s.replace('cold fish','cold chicken').replace('fish pieces','chicken pieces') for s in vs];variant(r,'chicken','Poached chicken variation',vi,vs);r['notes']+=' Allow about 15 minutes longer for the chicken variation; its cooking endpoint differs from fish.'
POACH='Bring {{fishwater}} to a gentle simmer in a wide pan. Add {{fish}} and poach for about 8–12 minutes, until the thickest part reaches 63°C (145°F) and flakes easily. Lift out, drain and break into large pieces, checking for bones. Spread in a shallow container and refrigerate promptly, within 2 hours of cooking, until cold, about 45 minutes.'

r=add(25,'Poblana Fish Platter with Garlic Mayonnaise',4,90,'Poached fish is covered with shredded lettuce and garlic mayonnaise, then finished with slices of hard-boiled egg.',[fish(600),water(1200,'fishwater'),yolks(2),oil(180),vinegar(15),salt(.5),I('garlic',3,'g','peeled garlic, crushed to a paste','Use the same weight of roasted garlic for a milder flavor.'),lettuce(150),pepper(.125),eggs(2),water(1000)], [POACH]+boil()+['Slice the cooled cooked eggs and refrigerate. Whisk {{yolks}} and {{salt}} in a clean bowl. Gradually whisk in {{oil}}, starting with drops, then a thin stream as the sauce thickens. Beat in {{garlic}}, then slowly add {{vinegar}}. Keep refrigerated.','Shred {{lettuce}} finely and toss with {{pepper}}. Arrange the cold fish in a low mound on a platter, cover with the lettuce and spread the mayonnaise over it. Garnish with the cooked egg slices and serve cold.',END],'The full original Poblana paragraph includes cooked boneless fish or chicken, lettuce and cooked-egg garnish. Missing fish, lettuce, oil and seasoning amounts are modern working quantities; the two yolks, garlic clove and tablespoon of vinegar are retained. Fresh white fish is chosen from the source’s non-salted fish options. The ambiguous cone instruction becomes a low fish-and-lettuce mound for stable serving.');finish(r);poultry(r)

r=add(27,'Mexican Layered Fish and Lettuce Mayonnaise',8,90,'Cold white fish and shredded lettuce form two layers separated and covered by a rich twelve-yolk vinegar mayonnaise.',[fish(1000),water(2000,'fishwater'),lettuce(250),yolks(12),oil(250),vinegar(45),salt(1)], [POACH,'Shred {{lettuce}} finely and drain or pat completely dry. Keep refrigerated.','Whisk {{yolks}} in a large clean bowl. Gradually whisk in {{oil}}, starting with drops and continuing in a thin stream, alternating with small additions of {{vinegar}}. Whisk in {{salt}}. Use commercially pasteurized yolks; this sauce is not cooked by beating.','Spread one third of the mayonnaise on a platter, followed by half the lettuce and half the cold fish. Repeat with another third of the mayonnaise, the remaining lettuce and remaining fish. Finish with the last third of the mayonnaise, covering the surface. Serve cold.',END],'The original half cuartillo is not a verified one-eighth liter. The 250 ml oil is an explicit modern working amount, not a recovered historical conversion. The source twelve yolks and alternating lettuce, fish and mayonnaise layers are retained. The final egg layer means the yolk-based sauce, not an additional unspecified egg garnish. Fish size, acid, salt and yield are supplied. Full poultry preparation is retained in a variation.');finish(r);poultry(r)

r=add(28,'Poblana Salsa Mahonesa',16,20,'A smooth two-yolk olive-oil mayonnaise combines a little vinegar with lemon, with the source’s vinegar-only option retained.',[yolks(2),oil(250),vinegar(10),lemon(15),salt(.5),pepper(.125)], ['Whisk {{yolks}} with {{vinegar|0.5}} in a clean bowl. Measure {{oil}} into a jug. Add it drop by drop while whisking, progressing to a thin stream as the sauce emulsifies. Alternate the later oil additions with small additions of {{lemon}}.','Gradually whisk in {{vinegar|0.5}}, {{salt}} and {{pepper}}. If too thick, add a teaspoon of cold drinking water; this optional adjustment changes the yield slightly.','If the emulsion breaks, put one additional commercially pasteurized yolk in a clean bowl and slowly whisk the broken sauce into it, a few drops at a time at first. Use a second additional pasteurized yolk only if needed. These conditional repair yolks are extra and increase the yield.',COLD],'The source gives two yolks but no total oil or acid volume. These are supplied modern working quantities. Initial vinegar, alternating oil and acid, final thinning and optional pepper are retained. One or two additional pasteurized yolks are a conditional rescue, not part of the normal measured batch.');eggsource(r)
vi=[dict(i,key='extraacid',name='white wine vinegar in place of lemon juice',substitution='Use the lemon base recipe if preferred.') if i['key']=='lemon' else copy.deepcopy(i) for i in r['ingredients']];vs=[s.replace('{{lemon}}','{{extraacid}}') for s in r['steps']];variant(r,'vinegar-only','Vinegar-only mayonnaise',vi,vs)

r=add(29,'Poblana Mayonesa o Bayoneta — Yolk-Rich Sauce',4,15,'A small, yolk-rich sauce uses one tablespoon of olive oil per yolk and a lemon finish; vinegar and green-herb variations preserve an equivalent source.',[yolks(2),oil(30),lemon(10),salt(.125),pepper(.0625)], ['Whisk {{yolks}}, {{salt}} and {{pepper}} in a small clean bowl. Add {{oil}} drop by drop while whisking constantly until evenly blended.','Slowly whisk in {{lemon}}. Continue until smooth; this low-oil source formula makes a softer, more yolk-forward sauce than a high-oil mayonnaise. Serve in small portions with already-cooked chilled fish or poultry.',COLD],'The original explicitly uses one tablespoon of oil per yolk. Two modern 15 ml tablespoons become 30 ml, not a high-oil replacement formula. Acid and seasonings are supplied modern quantities. The L.—E. A. source uses the same one-yolk/one-tablespoon-oil ratio with vinegar and optional parsley or tarragon. Its vinegar-first method and both green options are preserved as full named variations. The source quarter-hour beating is guidance for hand mixing, not egg cooking. Four small condiment servings are estimated.');eggsource(r)
vi=[vinegar(10) if i['key']=='lemon' else copy.deepcopy(i) for i in r['ingredients']]
vs=['Whisk {{yolks}}, {{salt}}, {{pepper}} and {{vinegar|0.1}} in a small clean bowl. Gradually whisk in {{oil}} drop by drop until evenly blended.','Slowly whisk in {{vinegar|0.9}} until smooth. For the source cooling method, set the bowl over a larger bowl of clean ice water while whisking, keeping all water out of the sauce. This is a soft, yolk-rich sauce. Serve in small portions with already-cooked chilled foods.',COLD];variant(r,'white-vinegar','White vinegar mayonnaise — L.—E. A.',vi,vs)
for name,amount in [('parsley',2),('tarragon',1)]:
 gi=copy.deepcopy(vi)+[I('herb',amount,'g','fresh '+name+' leaves, washed and very finely minced','Use the other named green-herb variation if preferred.')];gs=copy.deepcopy(vs);gs[0]=gs[0].replace('in a small clean bowl','and {{herb}} in a small clean bowl');variant(r,'green-'+name,'Green '+name+' mayonnaise',gi,gs)
s=src(26);aliases[s['id']]=dict(id=s['id'],canonicalId=r['id'],bodySha256=s['bodySha256'],reason='Equivalent yolk-rich sauce: both originals specify one tablespoon oil per yolk, salt/pepper and acid. Vinegar-first method, external cooling and parsley/tarragon variations retained in canonical recipe.');r['sourceAliases'].append(s['id']);r['source']+=' Equivalent source retained: '+s['recipe']['source'];records.pop(s['id'],None);merged=s

r=add(31,'Artusi Salsa Maionese',8,20,'A lemon mayonnaise made with olive oil and white pepper, with Artusi’s additional cooked-yolk version preserved.',[yolks(2),oil(100),lemon(30),salt(.25),I('whitepepper',.125,'tsp','ground white pepper','Use the same amount of black pepper; the color changes.')], ['Whisk {{yolks}} in a clean bowl. Add {{oil}} drop by drop at first, then in a thin stream while whisking until smooth and creamy.','Gradually whisk in {{lemon}}, then {{salt}} and {{whitepepper}}. Stop adding liquid if the sauce separates and whisk until smooth before proceeding. Serve with already-cooked fish or vegetables.',COLD],'The six-to-seven spoonfuls of oil become a modern 100 ml working amount, within six-to-seven modern 15 ml tablespoons. One lemon is standardized to 30 ml juice. The source permits more oil if absorbed; the measured version fixes the batch size. Pasteurized yolks replace uncooked unpasteurized yolks. Yield is estimated; the following salad specifies this sauce quantity for seven or eight people.');eggsource(r)
vi=copy.deepcopy(r['ingredients'])+[eggs(1),water(750)];vs=boil()+['Separate the cooked yolk and sieve it into a clean bowl; refrigerate the white for another dish.']+copy.deepcopy(r['steps']);vs[2]=vs[2].replace('Whisk {{yolks}} in a clean bowl.','Whisk {{yolks}} into the sieved cooked yolk.');variant(r,'added-cooked-yolk','With an additional cooked yolk',vi,vs);r['notes']+=' Allow about 35 minutes for the cooked-yolk variation, including cooking and cooling.'

r=add(30,'Artusi Insalata Maionese — Fish, Beet and Potato Salad',8,100,'Poached fish, beet, potato, lettuce and anchovies are mounded beneath mustard mayonnaise and decorated with alternating beet and potato slices.',[fish(600),water(1200,'fishwater'),I('beets',300,'g','small whole beets, scrubbed','Use the same weight of golden beets; color differs.'),water(1200,'beetwater'),I('potatoes',400,'g','small waxy potatoes, scrubbed','Use the same weight of another firm boiling potato.'),water(1500,'potatowater'),lettuce(150),I('anchovies',25,'g','oil-packed anchovy fillets, drained','Use the same weight of capers for a fish-free garnish flavor; the main dish still contains fish.'),I('dressoil',20,'ml','olive oil for the salad','Use the same volume of sunflower oil.'),I('dressvinegar',10,'ml','white wine vinegar for the salad','Use the same volume of cider vinegar.'),I('dresssalt',.25,'tsp','fine salt for the salad','Reduce or omit.'),yolks(2),oil(100),lemon(30),I('mustard',1,'tsp','prepared smooth mustard','Use the same volume of Dijon mustard.'),vinegar(5),salt(.25)], [POACH,'While the fish chills, put {{beets}} in a saucepan with {{beetwater}}. Bring to a boil, then simmer for 30–50 minutes until a knife enters easily. Drain and cool briefly, rub off the skins and slice thinly. Spread in a shallow dish and refrigerate until cold.','In another saucepan, cover {{potatoes}} with {{potatowater}}, adding more water only if needed. Bring to a boil and simmer for 15–25 minutes until tender. Drain, cool briefly, peel if desired and slice thinly. Spread in a shallow dish and refrigerate until cold.','Cut {{lettuce}} into finger-width strips and {{anchovies}} into small pieces. Reserve about one quarter of the cold beet and potato slices for the final garnish. Toss the remaining slices with the cold fish, lettuce and anchovies, then dress with {{dressoil}}, {{dressvinegar}} and {{dresssalt}}. Mound on a platter.','For the mayonnaise, whisk {{yolks}} in a clean bowl. Gradually whisk in {{oil}}, drop by drop at first, then in a thin stream. Slowly add {{lemon}}. Mix {{mustard}} with {{vinegar}}, then whisk into the sauce with {{salt}}.','Spread the mayonnaise over the salad mound. Decorate with the reserved beet and potato slices, alternating their colors. Serve cold.',END],'The original prefers fish and supplies this sauce quantity for seven or eight people. Modern fish and vegetable weights are supplied. The sauce follows Artusi 126 with mustard instead of pepper and a little additional vinegar, exactly as the salad instructs. Prepared mustard is a modern interpretation of senapa. Oil-packed boneless anchovies replace washed, deboned salt-packed fish. Optional capers and mild olives are retained in a named variation. The optional molded butter flower is decorative and explicitly not for eating in the source; it is omitted from the edible recipe.');finish(r)
vi=copy.deepcopy(r['ingredients'])+[I('capers',10,'g','capers, drained','Omit for a less briny salad.'),I('olives',3,'','mild green olives, pitted','Use the same number of mild black olives.')];vs=copy.deepcopy(r['steps']);vs[3]+=' Roughly chop {{olives}} and add to the salad with {{capers}} before shaping the mound.';variant(r,'capers-olives','With capers and mild olives',vi,vs)

assert len(newids)==6,len(newids)
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full source cooking, sauce and meaningful variations completed','repair-batch-025.py'))
db.execute('insert or replace into decisions values(?,?,?,?,?)',(merged['id'],merged['bodySha256'],'prepared-merge',aliases[merged['id']]['reason'],'repair-batch-025.py'))
db.commit();print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=1,totalOverrides=len(records),totalAliases=len(aliases))))

